  "claim": {
    "component_id": "C025",
    "value": "If multiple alignments fit, references conflict or overlap is insufficient, specifically dated histories that could distinguish the alternatives should be sought.",
    "scope": "Targeted follow-up under unresolved chronology; successful discrimination is not guaranteed.",
    "provenance": {
