          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the triggering conditions, the proposed follow-up and its possible discriminating role."
    }
  },
  "signal_basis": {
    "component_id": "C025_signal_basis",
    "value": "Candidate chronology remains unresolved when several alignments fit, references conflict or overlap is insufficient. Persistent mismatches, equally plausible shifts or unexplained changes in processing delays indicate this unresolved state.",
    "scope": "Under these conditions, suspend exact date assignment and retain alternatives pending discriminating evidence.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans state the unresolved chronology conditions, diagnostic observations and limits on date assignment."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C025_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the claim is SUPPORTED."
